import lookupData from "./vscode-icons-lookup.json";
import { basenameOfPath } from "./pathEntry";

/**
 * File-tree icon resolver over a slim lookup generated by
 * `scripts/sync-vscode-icons.mjs`: names, extensions, folders and languages map
 * straight to an icon, and the light theme lists only its overrides. The SVGs
 * ship with the app under a version-pinned path, so icons work offline and no
 * third party learns which file types are open.
 */

interface IconLookupSection {
  readonly file?: number;
  readonly folder?: number;
  readonly fileNames: Readonly<Record<string, number>>;
  readonly fileExtensions: Readonly<Record<string, number>>;
  readonly folderNames: Readonly<Record<string, number>>;
  readonly languageIds: Readonly<Record<string, number>>;
}

interface VscodeIconsLookup {
  readonly version: string;
  /** Icon file names without the `.svg` suffix. */
  readonly icons: ReadonlyArray<string>;
  readonly dark: IconLookupSection;
  readonly light: IconLookupSection;
  readonly extensionToLanguageId: Readonly<Record<string, string>>;
  readonly fileNameToLanguageId: Readonly<Record<string, string>>;
}

const lookup = lookupData as VscodeIconsLookup;
const VSCODE_ICONS_BASE_URL = `${import.meta.env.BASE_URL}vscode-icons/v${lookup.version}`;

const localLanguageIdByExtensionOverrides = {
  // Cursor rules files (*.mdc) are commonly treated as markdown in VSCode/Cursor.
  mdc: "markdown",
  // Upstream languages.ts currently maps .html to django-html before html.
  // Prefer the base HTML icon for standalone HTML files.
  html: "html",
  // Upstream languages.ts maps yml/yaml to specialized language ids that can produce
  // non-generic YAML icons (for example cloudfoundry/esphome). Prefer the base YAML icon
  // unless a more specific basename/extension match (e.g. azure-pipelines.yml) is found.
  yml: "yaml",
  yaml: "yaml",
} as const;

function extensionCandidates(fileName: string): string[] {
  const candidates = new Set<string>();
  if (fileName.includes(".")) {
    candidates.add(fileName);
  }
  let dotIndex = fileName.indexOf(".");
  while (dotIndex !== -1 && dotIndex < fileName.length - 1) {
    const candidate = fileName.slice(dotIndex + 1);
    if (candidate.length > 0) {
      candidates.add(candidate);
    }
    dotIndex = fileName.indexOf(".", dotIndex + 1);
  }
  return [...candidates];
}

/** The light theme only lists overrides; everything else falls back to dark. */
function resolveInSection(
  section: keyof Pick<
    IconLookupSection,
    "fileNames" | "fileExtensions" | "folderNames" | "languageIds"
  >,
  key: string,
  theme: "light" | "dark",
): number | undefined {
  return (theme === "light" ? lookup.light[section][key] : undefined) ?? lookup.dark[section][key];
}

function resolveLanguageFallbackIcon(basename: string, theme: "light" | "dark"): number | null {
  const fromBasenameLanguage = lookup.fileNameToLanguageId[basename];
  if (fromBasenameLanguage) {
    return resolveInSection("languageIds", fromBasenameLanguage, theme) ?? null;
  }

  for (const candidate of extensionCandidates(basename)) {
    const languageId =
      localLanguageIdByExtensionOverrides[
        candidate as keyof typeof localLanguageIdByExtensionOverrides
      ] ?? lookup.extensionToLanguageId[candidate];
    if (!languageId) continue;
    return resolveInSection("languageIds", languageId, theme) ?? null;
  }

  return null;
}

function resolveFileIcon(pathValue: string, theme: "light" | "dark"): number | undefined {
  const basename = basenameOfPath(pathValue).toLowerCase();
  const fromFileName = resolveInSection("fileNames", basename, theme);
  if (fromFileName !== undefined) return fromFileName;

  for (const candidate of extensionCandidates(basename)) {
    const fromExtension = resolveInSection("fileExtensions", candidate, theme);
    if (fromExtension !== undefined) return fromExtension;
  }

  const fromLanguage = resolveLanguageFallbackIcon(basename, theme);
  if (fromLanguage !== null) return fromLanguage;

  return theme === "light" ? (lookup.light.file ?? lookup.dark.file) : lookup.dark.file;
}

function resolveFolderIcon(pathValue: string, theme: "light" | "dark"): number | undefined {
  const basename = basenameOfPath(pathValue).toLowerCase();
  return (
    resolveInSection("folderNames", basename, theme) ??
    (theme === "light" ? (lookup.light.folder ?? lookup.dark.folder) : lookup.dark.folder)
  );
}

export function getVscodeIconUrlForEntry(
  pathValue: string,
  kind: "file" | "directory",
  theme: "light" | "dark",
): string {
  const iconIndex =
    kind === "directory" ? resolveFolderIcon(pathValue, theme) : resolveFileIcon(pathValue, theme);
  const iconName =
    (iconIndex !== undefined ? lookup.icons[iconIndex] : undefined) ??
    (kind === "directory" ? "default_folder" : "default_file");
  return `${VSCODE_ICONS_BASE_URL}/${iconName}.svg`;
}
